// Reads the form and turns the uploaded photo into a picture the writing model can read.
const item = $input.first();
const files = item.binary || {};
const key = Object.keys(files)[0];
if (!key) throw new Error('Add a product photo to the form.');
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const type = files[key].mimeType || 'image/jpeg';
const form = item.json;
return [{
  json: {
    product: String(form['Product name'] || '').trim(),
    brief: String(form['What should the ads say?'] || '').trim(),
    versions: Math.min(5, Math.max(2, parseInt(String(form['How many versions?'] || '3'), 10) || 3)),
    seconds: parseInt(String(form['Video length'] || '5'), 10) || 5,
    audio: !String(form['Voice and sound'] || 'Yes').startsWith('No'),
    image: `data:${type};base64,${buffer.toString('base64')}`,
  },
  binary: { photo: files[key] },
}];

