// One item per ad version. If something went wrong so far, one item that says what, in MartLLM's own words.
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
const stop = (problem) => [{ json: { problem: problem + ' Nothing was made and nothing was charged.' } }];
const photo = $('Save the photo').first().json;
if (!photo.id) return stop('MartLLM could not take the photo: ' + tidy(photo.error?.message || 'no reason given') + '.');
const reply = $input.first().json;
if (reply.error?.message) return stop('MartLLM could not write the ads: ' + tidy(reply.error.message) + '.');
const text = reply.choices?.[0]?.message?.content || '';
const found = text.match(/\{[\s\S]*\}/);
let plan;
try { plan = JSON.parse(found ? found[0] : text); } catch (e) {
  return stop('The writing model did not answer in the expected shape. Send the form again.');
}
const form = $('Get the photo ready').first().json;
const s = $('Settings').first().json;
const versions = (plan.versions || []).filter((v) => v && v.video_prompt).slice(0, form.versions);
if (!versions.length) return stop('The writing model returned no ad versions. Send the form again.');
// Each version carries the request both the price check and the start send, so the price is for exactly this video.
return versions.map((v, i) => ({ json: {
  n: i + 1,
  angle: String(v.angle || 'Version ' + (i + 1)),
  caption: String(v.caption || ''),
  request: {
    model: s.video_model,
    prompt: v.video_prompt,
    image_url: photo.id,
    duration_seconds: form.seconds,
    resolution: s.resolution,
    audio: form.audio,
    max_cost: s.max_cost_per_video_usd,
  },
} }));

// Puts each version next to its price. If MartLLM refused one, say so in its own words: nothing has started yet.
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
const versions = $('Versions written?').all().map((i) => i.json);
const quotes = $input.all().map((i) => i.json);
const limit = $('Settings').first().json.max_cost_per_video_usd;
const usd = (x) => '$' + Number(x).toFixed(2);
const stop = (problem) => [{ json: { problem: problem + ' Nothing was made and nothing was charged.' } }];
const rows = [];
for (const [i, v] of versions.entries()) {
  const q = quotes[i] || {};
  if (q.error?.message) return stop('MartLLM could not price version ' + v.n + ': ' + tidy(q.error.message) + '.');
  if (q.valid !== true) return stop('MartLLM could not price version ' + v.n + '.');
  if (q.within_max_cost === false) return stop('Version ' + v.n + ' can cost up to ' + usd(q.max_cost_usd) + ', more than the limit of ' + usd(limit) + ' per video set for this form.');
  rows.push({ ...v, price_usd: q.cost_usd, most_usd: q.max_cost_usd });
}
const total = rows.reduce((sum, r) => sum + r.price_usd, 0);
const most = rows.reduce((sum, r) => sum + r.most_usd, 0);
const esc = (t) => String(t).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const html = '<ul>' + rows.map((r) => '<li><b>Version ' + r.n + ': ' + esc(r.angle) + '</b> ' + usd(r.price_usd) + '</li>').join('') + '</ul>'
  + '<p><b>Total: about ' + usd(total) + '</b>' + (most - total >= 0.005 ? ' (never more than ' + usd(most) + ')' : '') + '. A video that is not made costs nothing.</p>';
return [{ json: { rows, total_usd: Math.round(total * 10000) / 10000, most_usd: Math.round(most * 10000) / 10000, html } }];

