// Keeps the jobs that started. A version MartLLM refused is listed on the last page with MartLLM's own message.
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
const replies = $input.all().map((i) => i.json);
const started = replies.filter((r) => r.id);
if (!started.length) {
  return [{ json: { problem: 'No video could start: ' + tidy(replies[0]?.error?.message || 'MartLLM did not accept the request') + '. Nothing was charged.' } }];
}
return started.map((r) => ({ json: r }));

// Looks at every job together. While any is still being made, all go round the loop again.
// After 45 checks (15 minutes) it stops waiting; those jobs still finish and show in your MartLLM dashboard.
const jobs = $input.all().map((i) => i.json);
const busy = jobs.some((j) => ['queued', 'running'].includes(j.status));
const waiting = busy && $runIndex < 45;
return jobs.map((j) => ({ json: { ...j, waiting } }));

// Passes on the videos that were made. If none was, one item with MartLLM's own reasons.
const jobs = $input.all().map((i) => i.json);
const made = jobs.filter((j) => j.status === 'succeeded' && j.results?.[0]?.url);
if (!made.length) {
  return [{ json: { problem: jobs.map((j) => 'Version ' + j.metadata?.version + ': ' + (j.error?.message ? String(j.error.message).replace(/[.\s]+$/, '') : (['queued', 'running'].includes(j.status) ? 'still being made after 15 minutes; it will show in your MartLLM dashboard' : 'it ended as ' + j.status))).join('.\n') + '.\nNothing was charged.' } }];
}
return made.map((j) => ({ json: j }));

// One item with every video file, and a short report: what was made, what each cost, what was not made and why.
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
const made = $('Any made?').all().map((i) => i.json);
const all = $('Any still being made?').all().map((i) => i.json);
const starts = $('Start each video').all().map((i) => i.json);
const asked = $('Versions to make').all().map((i) => i.json);
const usd = (x) => '$' + Number(x).toFixed(2);
const binary = {};
const lines = [];
let total = 0;
$input.all().forEach((item, i) => {
  const job = made[i];
  const n = job.metadata?.version || String(i + 1);
  const file = item.binary?.video;
  if (!file) return;
  binary['video_' + n] = { ...file, fileName: 'ad-version-' + n + '.mp4' };
  const cost = job.usage?.cost_usd ?? job.estimated_cost_usd;
  total += Number(cost) || 0;
  lines.push('Version ' + n + ' (' + (job.metadata?.angle || '') + '): made, ' + usd(cost) + (job.usage?.cost_usd == null ? ' expected' : ''));
});
for (const job of all) {
  if (job.status !== 'succeeded') lines.push('Version ' + job.metadata?.version + ': not made, ' + (job.error?.message ? String(job.error.message).replace(/[.\s]+$/, '') : (['queued', 'running'].includes(job.status) ? 'still being made after 15 minutes; it will show in your MartLLM dashboard' : 'it ended as ' + job.status)));
}
starts.forEach((r, i) => { if (!r.id) lines.push('Version ' + asked[i]?.n + ': not started, ' + tidy(r.error?.message || 'MartLLM did not accept the request')); });
if (!Object.keys(binary).length) throw new Error('The videos were made but could not be downloaded. They are in your MartLLM dashboard for about 3 hours.');
return [{ json: { report: lines.join('.\n') + '.\nTotal: ' + usd(total) + '.', total_usd: Math.round(total * 10000) / 10000, files: Object.keys(binary).join(',') }, binary }];
